internal static class WidgetTheme
{
    internal static readonly Brush Primary = new SolidColorBrush(Color.FromRgb(250,246,240)); internal static readonly Brush Secondary = new SolidColorBrush(Color.FromRgb(211,202,211)); internal static readonly Brush Tertiary = new SolidColorBrush(Color.FromRgb(173,162,177)); internal static readonly Brush Hairline = new SolidColorBrush(Color.FromArgb(42,255,255,255)); internal static readonly CornerRadius CardRadius = new(24); internal static readonly Thickness CardPadding = new(14);
    internal static LinearGradientBrush PlumSurface() => Gradient(Color.FromRgb(65,31,51),Color.FromRgb(28,26,42));
    internal static LinearGradientBrush Gradient(Color a, Color b) => new(new GradientStopCollection { new(a,0),new(b,1)},135);
    internal static Border Card(UIElement child) => Card(new CanvasItem(), child, null);
    internal static Border Card(CanvasItem item, UIElement child, byte[]? art)
    {
        var (a,b) = Resolve(item,art); return new Border { Child=child, Background=Gradient(a,b), BorderBrush=new SolidColorBrush(Color.FromArgb(46,255,255,255)), BorderThickness=new Thickness(1), CornerRadius=CardRadius, Padding=CardPadding, ClipToBounds=true, Effect=new DropShadowEffect { Color=Colors.Black,ShadowDepth=4,BlurRadius=20,Opacity=.3 } };
    }
    internal static (Color,Color) Resolve(CanvasItem item, byte[]? bytes)
    {
        if (item.Theme==WidgetThemeKind.Light) return (Color.FromRgb(249,248,246),Color.FromRgb(231,233,238)); if(item.Theme==WidgetThemeKind.Dark)return(Color.FromRgb(37,40,49),Color.FromRgb(17,19,26)); if(item.Theme==WidgetThemeKind.Rose)return(Color.FromRgb(117,51,75),Color.FromRgb(52,27,47)); if(item.Theme==WidgetThemeKind.Ocean)return(Color.FromRgb(35,94,126),Color.FromRgb(20,39,73)); if(item.Theme==WidgetThemeKind.Mint)return(Color.FromRgb(43,111,95),Color.FromRgb(22,58,54));
        if(bytes is not null) try { using var map=SKBitmap.Decode(bytes); if(map is not null) { long r=0,g=0,b=0,n=0; for(var y=0;y<map.Height;y+=Math.Max(1,map.Height/20))for(var x=0;x<map.Width;x+=Math.Max(1,map.Width/20)){var p=map.GetPixel(x,y);r+=p.Red;g+=p.Green;b+=p.Blue;n++;} return(Color.FromRgb((byte)Math.Clamp(r/n,32,150),(byte)Math.Clamp(g/n,24,130),(byte)Math.Clamp(b/n,32,150)),Color.FromRgb(25,28,38)); }}catch(Exception){}
        return PlumSurface().GradientStops is { } stops ? (stops[0].Color,stops[1].Color) : (Colors.Black,Colors.Black);
    }
    internal static ControlTemplate RoundButtonTemplate(){var border=new FrameworkElementFactory(typeof(Border));border.SetValue(Border.CornerRadiusProperty,new CornerRadius(99));border.SetBinding(Border.BackgroundProperty,new System.Windows.Data.Binding("Background"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});var p=new FrameworkElementFactory(typeof(ContentPresenter));p.SetBinding(ContentPresenter.ContentProperty,new System.Windows.Data.Binding("Content"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});p.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);p.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(p);return new ControlTemplate(typeof(Button)){VisualTree=border};}
}

internal sealed class NowPlayingItemContent : IDesktopItemContent
{
    private readonly CanvasItem item; private readonly INowPlayingService service; private readonly Border root; private readonly Border artFrame; private readonly Image art=new(){Stretch=Stretch.UniformToFill}; private readonly TextBlock title=new(){FontSize=18,FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis}; private readonly TextBlock artist=new(){FontSize=12}; private readonly TextBlock elapsed=new(){FontSize=10}; private readonly TextBlock remaining=new(){FontSize=10}; private readonly Slider seek=new(){Minimum=0,Maximum=1,Opacity=.01}; private readonly Border fill=new(){Height=4,CornerRadius=new CornerRadius(2),HorizontalAlignment=HorizontalAlignment.Left}; private readonly Grid timeline=new(){Height=14}; private readonly Button previous=ButtonFor("M10,3V13M13,4V12L4,8Z",40), play=ButtonFor("M5,3L14,8L5,13Z",46), next=ButtonFor("M6,4V12L15,8ZM3,3V13",40); private readonly StackPanel bars=new(){Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(6,0,0,0)}; private readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(250)}; private IDisposable? lease; private bool active,dragging; private NowPlayingSnapshot shown=NowPlayingSnapshot.Empty;
    internal NowPlayingItemContent(CanvasItem item, INowPlayingService service)
    {
        this.item=item;this.service=service; artFrame=new Border{Width=94,Height=94,CornerRadius=new CornerRadius(17),ClipToBounds=true,Child=art,Margin=new Thickness(0,0,14,0)}; artFrame.MouseLeftButtonUp+=Activate; title.MouseLeftButtonUp+=Activate;
        var info=new StackPanel{VerticalAlignment=VerticalAlignment.Center}; info.Children.Add(title);info.Children.Add(artist); var head=new Grid();head.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});head.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});head.Children.Add(artFrame);Grid.SetColumn(info,1);head.Children.Add(info);
        timeline.Children.Add(new Border{Height=4,CornerRadius=new CornerRadius(2),Background=new SolidColorBrush(Color.FromArgb(70,255,255,255)),VerticalAlignment=VerticalAlignment.Center});timeline.Children.Add(fill);timeline.Children.Add(seek);timeline.SizeChanged+=(_,_)=>PaintTimeline(); seek.PreviewMouseLeftButtonDown+=(_,_)=>dragging=true;seek.PreviewMouseLeftButtonUp+=async(_,_)=>{dragging=false;if(shown.CanSeek)await service.SeekAsync(TimeSpan.FromSeconds(seek.Value));};
        previous.Click+=async(_,_)=>await service.PreviousAsync();play.Click+=async(_,_)=>await service.PlayPauseAsync();next.Click+=async(_,_)=>await service.NextAsync();for(var i=0;i<7;i++)bars.Children.Add(new Border{Width=3,Height=5+i%4*5,Margin=new Thickness(1),Background=new SolidColorBrush(Color.FromRgb(250,208,190)),VerticalAlignment=VerticalAlignment.Center});
        var time=new Grid();time.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});time.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});time.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});time.Children.Add(elapsed);Grid.SetColumn(remaining,2);time.Children.Add(remaining);var controls=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};controls.Children.Add(previous);controls.Children.Add(play);controls.Children.Add(next);controls.Children.Add(bars);var panel=new StackPanel();panel.Children.Add(head);panel.Children.Add(timeline);panel.Children.Add(time);panel.Children.Add(controls);root=WidgetTheme.Card(item,panel,null);timer.Tick+=(_,_)=>Update(service.Snapshot);Update(service.Snapshot);
    }
    public UIElement View=>root; public bool HasInteractiveControls=>true; public bool IsInteractiveHit(Point p){var hit=root.InputHitTest(p)as DependencyObject;while(hit is not null){if(hit is Button or Slider||ReferenceEquals(hit,artFrame)||ReferenceEquals(hit,title))return true;hit=VisualTreeHelper.GetParent(hit);}return false;}
    public void SetActive(bool v){if(active==v)return;active=v;if(v){service.SnapshotChanged+=Changed;lease=service.Acquire();timer.Start();Update(service.Snapshot);}else{service.SnapshotChanged-=Changed;lease?.Dispose();lease=null;timer.Stop();}}
    private void Changed(object? s,NowPlayingSnapshot n)=>root.Dispatcher.BeginInvoke(()=>Update(n)); private void Activate(object? s,System.Windows.Input.MouseButtonEventArgs e){new ActivationService().TryActivate(shown.SourceApp);e.Handled=true;}
    private void Update(NowPlayingSnapshot n){shown=n;title.Text=n.Title;artist.Text=n.Artist;artist.Visibility=string.IsNullOrWhiteSpace(n.Artist)?Visibility.Collapsed:Visibility.Visible;artFrame.Visibility=item.NowPlaying.ShowAlbumArt?Visibility.Visible:Visibility.Collapsed;previous.IsEnabled=n.CanPrevious;next.IsEnabled=n.CanNext;play.IsEnabled=n.CanPlayPause;play.Content=Icon(n.State==NowPlayingState.Playing?"M5,3H8V13H5ZM11,3H14V13H11Z":"M5,3L14,8L5,13Z");var show=item.NowPlaying.ShowTimeline&&n.End>TimeSpan.Zero;timeline.Visibility=show?Visibility.Visible:Visibility.Collapsed;seek.IsEnabled=n.CanSeek;seek.Maximum=Math.Max(1,n.End.TotalSeconds);if(!dragging)seek.Value=Math.Clamp(n.Position.TotalSeconds,0,seek.Maximum);elapsed.Text=n.Position.ToString(@"m\:ss");remaining.Text="−"+(n.End>n.Position?n.End-n.Position:TimeSpan.Zero).ToString(@"m\:ss");PaintTimeline();for(var i=0;i<bars.Children.Count;i++)bars.Children[i].Height=n.State==NowPlayingState.Playing?6+(i*7+(int)DateTime.UtcNow.Millisecond/120)%17:5;}
    private void PaintTimeline()=>fill.Width=Math.Max(0,timeline.ActualWidth*(seek.Maximum==0?0:seek.Value/seek.Maximum)); internal void Refresh()=>Update(service.Snapshot); public void Dispose(){SetActive(false);}
    private static Button ButtonFor(string data,double size)=>new(){Width=size,Height=size,Margin=new Thickness(3),Padding=new Thickness(0),BorderThickness=new Thickness(0),Background=Brushes.Transparent,Foreground=WidgetTheme.Primary,Content=Icon(data),Template=WidgetTheme.RoundButtonTemplate()};private static Viewbox Icon(string d)=>new(){Width=18,Height=18,Child=new Path{Data=Geometry.Parse(d),Fill=Brushes.White,Stretch=Stretch.Uniform}};
}

internal sealed class SystemMonitorItemContent : IDesktopItemContent
{
    private readonly CanvasItem item;private readonly ISystemMetricsService service;private readonly Border root;private readonly Ring cpu=new("CPU"),ram=new("RAM"),gpu=new("GPU");private readonly TextBlock down=new(),up=new(),clock=new(){FontSize=10};private IDisposable? lease;private bool active;
    internal SystemMonitorItemContent(CanvasItem item,ISystemMetricsService service){this.item=item;this.service=service;var heading=new TextBlock{Text="◈  SYSTEM STATUS",FontSize=10,FontWeight=FontWeights.SemiBold};var rings=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};rings.Children.Add(cpu);rings.Children.Add(ram);rings.Children.Add(gpu);var net=new Grid{Height=32,Margin=new Thickness(0,14,0,0)};net.ColumnDefinitions.Add(new ColumnDefinition());net.ColumnDefinitions.Add(new ColumnDefinition());net.Children.Add(Pill(down));var b=Pill(up);Grid.SetColumn(b,1);net.Children.Add(b);var p=new StackPanel();p.Children.Add(heading);p.Children.Add(clock);p.Children.Add(rings);p.Children.Add(net);root=WidgetTheme.Card(item,p,null);Update(service.Snapshot);}
    public UIElement View=>root;public void SetActive(bool v){if(active==v)return;active=v;if(v){service.SnapshotChanged+=Changed;lease=service.Acquire();Update(service.Snapshot);}else{service.SnapshotChanged-=Changed;lease?.Dispose();lease=null;}}private void Changed(object? s,SystemMetricsSnapshot n)=>root.Dispatcher.BeginInvoke(()=>Update(n));private void Update(SystemMetricsSnapshot n){cpu.Set(n.Cpu);ram.Set(n.Memory);gpu.Set(n.Gpu);clock.Text="CPU  "+ProcessorClock.Read();down.Text="↓ Download  "+n.Download.Text;up.Text="↑ Upload  "+n.Upload.Text;cpu.Visibility=item.SystemMonitor.ShowCpu?Visibility.Visible:Visibility.Collapsed;ram.Visibility=item.SystemMonitor.ShowMemory?Visibility.Visible:Visibility.Collapsed;gpu.Visibility=item.SystemMonitor.ShowGpu?Visibility.Visible:Visibility.Collapsed;}internal void Refresh()=>Update(service.Snapshot);public void Dispose()=>SetActive(false);private static Border Pill(TextBlock t)=>new(){Margin=new Thickness(0,0,3,0),CornerRadius=new CornerRadius(16),Background=new SolidColorBrush(Color.FromArgb(30,255,255,255)),Child=t,Padding=new Thickness(8,7,8,7)};
    private sealed class Ring:StackPanel{private readonly TextBlock value=new(){HorizontalAlignment=HorizontalAlignment.Center,FontWeight=FontWeights.Bold};private readonly Path arc=new(){StrokeThickness=5,StrokeStartLineCap=PenLineCap.Round};internal Ring(string name){Width=70;var c=new Canvas{Width=60,Height=60};c.Children.Add(new Ellipse{Width=60,Height=60,Stroke=new SolidColorBrush(Color.FromArgb(80,255,255,255)),StrokeThickness=5});c.Children.Add(arc);Children.Add(c);Children.Add(value);Children.Add(new TextBlock{Text=name,FontSize=9,HorizontalAlignment=HorizontalAlignment.Center});}internal void Set(MetricValue m){value.Text=m.Availability==MetricAvailability.Loading?"…":m.Availability==MetricAvailability.Unavailable?"--":$"{m.Value:0}%";arc.Stroke=m.Availability==MetricAvailability.Available?new SolidColorBrush(Color.FromRgb(115,205,246)):Brushes.Gray;var a=Math.Clamp(m.Value??0,0,99.99)*3.6*Math.PI/180;arc.Data=new PathGeometry([new PathFigure(new Point(30,4),[new ArcSegment(new Point(30+26*Math.Sin(a),30-26*Math.Cos(a)),new Size(26,26),0,a>Math.PI,SweepDirection.Clockwise,true)],false)]);}}
}
internal static class ProcessorClock{[StructLayout(LayoutKind.Sequential)]private struct P{public uint Number,MaxMhz,CurrentMhz,MhzLimit,MaxIdle,CurrentIdle;}[DllImport("powrprof.dll")]private static extern uint CallNtPowerInformation(int level,IntPtr input,int inputLength,[Out] P[] output,int outputLength);internal static string Read(){try{var p=new P[Math.Max(1,Environment.ProcessorCount)];return CallNtPowerInformation(11,IntPtr.Zero,0,p,Marshal.SizeOf<P>()*p.Length)==0?SystemMetricMath.FormatProcessorClock(p.Select(x=>x.CurrentMhz)):"-- GHz";}catch(Exception){return "-- GHz";}}}
